<template>
  <section class="page">
    <header><div><h1>文档解析中心</h1><p>将 PDF/Word 异步解析、分块并入库。任务状态由 Redis + Celery Worker 驱动。</p></div><el-button type="primary" @click="createVisible = true">创建文档库</el-button></header>
    <el-alert v-if="error" type="error" :title="error" show-icon :closable="false" />
    <el-empty v-if="!loading && libraries.length === 0" description="暂无自定义文档库，请先创建一个知识库。" />
    <template v-else>
      <el-select v-model="selectedSlug" placeholder="选择文档库" class="library-select" @change="loadJobs"><el-option v-for="item in libraries" :key="item.slug" :label="item.name" :value="item.slug" /></el-select>
      <el-card v-if="selectedSlug" class="upload-card" shadow="never"><el-form inline><el-form-item label="分块大小"><el-input-number v-model="chunkSize" :min="200" :max="2000" /></el-form-item><el-form-item label="重叠字符"><el-input-number v-model="chunkOverlap" :min="0" :max="chunkSize - 1" /></el-form-item><el-form-item><input ref="fileInput" type="file" accept=".pdf,.docx" multiple hidden @change="upload" /><el-button type="primary" :loading="uploading" @click="fileInput?.click()">上传 PDF / Word（可多选）</el-button></el-form-item></el-form></el-card>
      <el-table :data="jobs" v-loading="loading" empty-text="该知识库还没有上传文件。"><el-table-column prop="original_filename" label="源文件" min-width="230" /><el-table-column prop="file_type" label="格式" width="80" /><el-table-column label="状态" width="150"><template #default="{ row }"><el-tag :type="statusType(row.status)">{{ statusText(row.status) }} {{ row.progress }}%</el-tag></template></el-table-column><el-table-column label="解析统计" min-width="170"><template #default="{ row }">{{ stats(row) }}</template></el-table-column><el-table-column prop="error_message" label="失败原因" min-width="180" /><el-table-column label="操作" width="140" fixed="right"><template #default="{ row }"><el-button v-if="row.status === 'READY'" text type="primary" @click="showDetail(row.id)">详情</el-button><el-button v-if="row.status === 'FAILED'" text type="warning" @click="retry(row.id)">重试</el-button></template></el-table-column></el-table>
    </template>
    <el-dialog v-model="createVisible" title="创建自定义文档库" width="440px"><el-form label-position="top"><el-form-item label="名称"><el-input v-model="form.name" /></el-form-item><el-form-item label="唯一标识"><el-input v-model="form.slug" /></el-form-item><el-form-item label="法律领域"><el-input v-model="form.law_area" /></el-form-item></el-form><template #footer><el-button @click="createVisible = false">取消</el-button><el-button type="primary" :loading="saving" @click="createLibrary">创建</el-button></template></el-dialog>
<el-drawer v-model="detailVisible" title="文档解析详情" size="58%" :destroy-on-close="true"><el-skeleton v-if="detailLoading" :rows="8" animated /><template v-else-if="detail"><el-descriptions :column="3" border><el-descriptions-item label="页数">{{ detail.page_count }}</el-descriptions-item><el-descriptions-item label="表格">{{ detail.table_count }}</el-descriptions-item><el-descriptions-item label="关联候选">{{ detail.relations_count }}</el-descriptions-item></el-descriptions><template v-if="detail.structure"><el-alert class="detail-section" type="info" :closable="false" :title="`结构化类型：${detail.structure.document_type}（${detail.structure.status}）`" /><el-empty v-if="detail.structure.status === 'FAILED'" description="结构化解析失败，文档仍可按普通文本检索。" /><el-alert v-else-if="detail.structure.document_type === 'general'" class="detail-section" type="warning" :closable="false" title="未识别为合同或判决书，已按通用文档入库。" /><el-descriptions v-else class="detail-section" :column="1" border><el-descriptions-item v-for="field in structureFields" :key="field.key"><template #label>{{ field.label }} · 第 {{ field.pageNumber }} 页</template><div>{{ field.value }}</div><p class="evidence-text">原文依据：{{ field.evidenceText }}</p><el-tag size="small" type="info">{{ field.method === 'llm_verified' ? '模型补充，已核验原文' : '规则提取' }}</el-tag></el-descriptions-item></el-descriptions></template><el-collapse class="detail-section"><el-collapse-item v-for="item in detailPages" :key="item.page_number" :title="`第 ${item.page_number} 页 · ${item.source === 'ocr' ? 'OCR 识别' : '文本层提取'}`"><el-alert v-if="item.parse_warnings.length" type="warning" :closable="false" :title="item.parse_warnings.join('；')" /><p class="page-text">{{ item.raw_text }}</p><el-tag v-for="(_, index) in item.tables" :key="index" type="info" class="table-tag">表格 {{ index + 1 }} · {{ item.tables[index].method }}</el-tag></el-collapse-item></el-collapse></template><el-empty v-else description="暂无可展示的解析结果" /></el-drawer>
  </section>
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { documentApi, type DocumentJob, type DocumentPageResult, type DocumentResult } from '@/api/documents'
import { knowledgeBaseApi, type KnowledgeBase } from '@/api/knowledgeBases'

const libraries = ref<KnowledgeBase[]>([]); const jobs = ref<DocumentJob[]>([]); const selectedSlug = ref(''); const loading = ref(false); const uploading = ref(false); const saving = ref(false); const error = ref(''); const createVisible = ref(false); const detailVisible = ref(false); const detailLoading = ref(false); const detail = ref<DocumentResult>(); const detailPages = ref<DocumentPageResult[]>([]); const fileInput = ref<HTMLInputElement>(); const chunkSize = ref(800); const chunkOverlap = ref(120); const form = ref({ name: '', slug: '', law_area: '' }); let timer: number | undefined
type TraceableField = { value: string; page_number: number; evidence_text: string; extraction_method: string }
const structureLabels: Record<string, string> = { parties: '当事人', subject: '标的 / 工作内容', remuneration: '价款 / 报酬', performance: '履行', breach: '违约责任', exemption: '免责', dispute_resolution: '争议解决', jurisdiction: '管辖', term: '期限', case_cause: '案由', claims: '诉讼请求', facts: '查明事实', court_reasoning: '法院认为', judgment_result: '裁判结果' }
const isTraceableField = (value: unknown): value is TraceableField => typeof value === 'object' && value !== null && typeof (value as TraceableField).value === 'string' && typeof (value as TraceableField).page_number === 'number' && typeof (value as TraceableField).evidence_text === 'string' && typeof (value as TraceableField).extraction_method === 'string'
const structureFields = computed(() => Object.entries(detail.value?.structure?.content ?? {}).flatMap(([key, value]) => {
  if (!isTraceableField(value)) return []
  return [{ key, label: structureLabels[key] ?? key, value: value.value, pageNumber: value.page_number, evidenceText: value.evidence_text, method: value.extraction_method }]
}))
const hasActiveJob = computed(() => jobs.value.some(job => ['UPLOADED', 'PARSING', 'CHUNKING', 'INDEXING'].includes(job.status)))
const statusText = (status: DocumentJob['status']) => ({ UPLOADED: '已接收', PARSING: '解析中', CHUNKING: '分块中', INDEXING: '入库中', READY: '已完成', FAILED: '失败' })[status]
const statusType = (status: DocumentJob['status']) => ({ UPLOADED: 'info', PARSING: 'warning', CHUNKING: 'warning', INDEXING: 'warning', READY: 'success', FAILED: 'danger' }[status])
const stats = (job: DocumentJob) => `${job.page_count ?? '—'} 页 · ${job.character_count ?? '—'} 字 · ${job.chunk_count ?? '—'} chunks`
async function loadLibraries() { loading.value = true; try { libraries.value = (await knowledgeBaseApi.list()).filter(item => item.type === 'document'); if (!selectedSlug.value && libraries.value[0]) selectedSlug.value = libraries.value[0].slug; if (selectedSlug.value) await loadJobs() } catch { error.value = '文档库列表加载失败，请确认后端服务已启动。' } finally { loading.value = false } }
async function loadJobs() { if (!selectedSlug.value) return; jobs.value = await documentApi.list(selectedSlug.value); if (hasActiveJob.value && timer === undefined) timer = window.setInterval(loadJobs, 2000); if (!hasActiveJob.value && timer !== undefined) { window.clearInterval(timer); timer = undefined } }
async function createLibrary() { saving.value = true; try { const library = await documentApi.createLibrary(form.value); createVisible.value = false; selectedSlug.value = library.slug; form.value = { name: '', slug: '', law_area: '' }; await loadLibraries(); ElMessage.success('文档库已创建') } finally { saving.value = false } }
async function upload(event: Event) { const files = Array.from((event.target as HTMLInputElement).files ?? []); if (!files.length || !selectedSlug.value) return; uploading.value = true; try { if (files.length === 1) { await documentApi.upload(selectedSlug.value, files[0], chunkSize.value, chunkOverlap.value); ElMessage.success('文件已进入异步解析队列') } else { const result = await documentApi.uploadBatch(selectedSlug.value, files, chunkSize.value, chunkOverlap.value); const succeeded = result.items.filter(item => item.job).length; const failed = result.items.length - succeeded; ElMessage.success(`已提交 ${succeeded} 个文件${failed ? `，${failed} 个文件未提交` : ''}`) } await loadJobs() } finally { uploading.value = false; (event.target as HTMLInputElement).value = '' } }
async function retry(id: string) { await documentApi.retry(id); await loadJobs(); ElMessage.success('已重新投递任务') }
async function showDetail(id: string) { detailVisible.value = true; detailLoading.value = true; try { const [result, pages] = await Promise.all([documentApi.result(id), documentApi.pages(id)]); detail.value = result; detailPages.value = pages.items } catch { ElMessage.error('文档详情加载失败') } finally { detailLoading.value = false } }
onMounted(loadLibraries); onBeforeUnmount(() => { if (timer !== undefined) window.clearInterval(timer) })
</script>

<style scoped>.page { max-width: 1240px; margin: 0 auto; } header { margin-bottom: 24px; display: flex; justify-content: space-between; align-items: flex-start; } h1 { margin: 0; color: #0f1f3d; font-family: 'Noto Serif SC', STSong, serif; } p { color: #606266; }.library-select { width: 320px; margin-bottom: 16px; }.upload-card { margin-bottom: 16px; }.detail-section { margin-top: 16px; }.evidence-text { margin: 8px 0; color: #909399; white-space: pre-wrap; }.page-text { white-space: pre-wrap; }.table-tag { margin: 8px 8px 0 0; }</style>
